select count(*) as n, md5(string_agg(h, '' order by h)) as h from (select md5(concat_ws(chr(31), "path", "title", "kind", "module", "format", "artifact_url", "docs_id", "tab_name", "rev", "content", "pdf_path", "sha256")) h from public.documents where "path" in ('modules/F1-histories-of-making/docs/10-unit-specs-batch-1/06-f1-14-copying-and-counterfeit.md', 'modules/F1-histories-of-making/docs/10-unit-specs-batch-1/07-f1-15-ornament-and-the-exhibition.md')) s;